"""TinyTorch losses module.

Extracted from CS249R Module 04: Loss Functions.
NumPy-only implementation for educational purposes.
"""

from __future__ import annotations

import numpy as np

from cohezion.tinytorch.tensor import Tensor


def mse_loss(predictions: Tensor, targets: Tensor) -> Tensor:
    """Mean Squared Error loss for regression."""
    diff = predictions.data - targets.data
    return Tensor(np.mean(diff ** 2))


def mse_loss_gradient(predictions: Tensor, targets: Tensor) -> Tensor:
    """Gradient of MSE loss w.r.t. predictions."""
    n = predictions.data.size
    return Tensor(2.0 * (predictions.data - targets.data) / n)


def cross_entropy_loss(logits: Tensor, targets: Tensor) -> Tensor:
    """Cross-entropy loss for multi-class classification."""
    shifted = logits.data - logits.data.max(axis=-1, keepdims=True)
    exp_logits = np.exp(shifted)
    probs = exp_logits / exp_logits.sum(axis=-1, keepdims=True)
    probs = np.clip(probs, 1e-7, 1 - 1e-7)

    if targets.data.ndim == 1:
        batch_size = logits.data.shape[0]
        log_probs = -np.log(probs[np.arange(batch_size), targets.data.astype(int)])
        return Tensor(np.mean(log_probs))
    return Tensor(-np.mean(np.sum(targets.data * np.log(probs), axis=-1)))


def binary_cross_entropy_loss(predictions: Tensor, targets: Tensor) -> Tensor:
    """Binary cross-entropy for binary classification."""
    p = np.clip(predictions.data, 1e-7, 1 - 1e-7)
    loss = -(targets.data * np.log(p) + (1 - targets.data) * np.log(1 - p))
    return Tensor(np.mean(loss))


def huber_loss(predictions: Tensor, targets: Tensor, delta: float = 1.0) -> Tensor:
    """Huber loss: MSE for small errors, MAE for large. Robust to outliers."""
    diff = np.abs(predictions.data - targets.data)
    loss = np.where(diff <= delta, 0.5 * diff ** 2, delta * (diff - 0.5 * delta))
    return Tensor(np.mean(loss))


def l1_loss(predictions: Tensor, targets: Tensor) -> Tensor:
    """L1 (Mean Absolute Error) loss."""
    return Tensor(np.mean(np.abs(predictions.data - targets.data)))


LOSSES = {
    "mse": mse_loss, "cross_entropy": cross_entropy_loss,
    "binary_cross_entropy": binary_cross_entropy_loss,
    "huber": huber_loss, "l1": l1_loss,
}

"""TinyTorch dataloader module.

Extracted from CS249R Module 05: Data Loading.
NumPy-only implementation for educational purposes.
"""

from __future__ import annotations

import numpy as np

from cohezion.tinytorch.tensor import Tensor


class Dataset:
    """Base dataset class. Subclass and implement __getitem__ and __len__."""

    def __getitem__(self, idx: int) -> tuple:
        raise NotImplementedError

    def __len__(self) -> int:
        raise NotImplementedError


class TensorDataset(Dataset):
    """Dataset wrapping tensors. Each sample is a tuple of corresponding elements."""

    def __init__(self, *tensors: Tensor):
        assert all(t.shape[0] == tensors[0].shape[0] for t in tensors)
        self.tensors = tensors

    def __getitem__(self, idx: int) -> tuple[Tensor, ...]:
        return tuple(Tensor(t.data[idx]) for t in self.tensors)

    def __len__(self) -> int:
        return self.tensors[0].shape[0]


class DataLoader:
    """Iterable data loader with batching and shuffling."""

    def __init__(self, dataset: Dataset, batch_size: int = 32, shuffle: bool = True):
        self.dataset = dataset
        self.batch_size = batch_size
        self.shuffle = shuffle

    def __iter__(self):
        n = len(self.dataset)
        indices = np.arange(n)
        if self.shuffle:
            np.random.shuffle(indices)

        for start in range(0, n, self.batch_size):
            batch_indices = indices[start:start + self.batch_size]
            batch = [self.dataset[i] for i in batch_indices]

            # Collate: stack each element across the batch
            collated = []
            for elem_idx in range(len(batch[0])):
                stacked = np.stack([b[elem_idx].data for b in batch])
                collated.append(Tensor(stacked))

            yield tuple(collated)

    def __len__(self) -> int:
        return (len(self.dataset) + self.batch_size - 1) // self.batch_size


def train_test_split(
    *arrays: Tensor,
    test_size: float = 0.2,
    seed: int | None = None,
) -> list[Tensor]:
    """Split arrays into train and test sets."""
    if seed is not None:
        np.random.seed(seed)

    n = arrays[0].shape[0]
    indices = np.random.permutation(n)
    split_idx = int(n * (1 - test_size))
    train_idx, test_idx = indices[:split_idx], indices[split_idx:]

    result = []
    for arr in arrays:
        result.append(Tensor(arr.data[train_idx]))
        result.append(Tensor(arr.data[test_idx]))
    return result

"""TinyTorch autograd module.

Extracted from CS249R Module 06: Automatic Differentiation.
NumPy-only implementation for educational purposes.
"""

from __future__ import annotations

import numpy as np


class Value:
    """Scalar value with automatic differentiation.

    Tracks computation graph and computes gradients via backpropagation.
    Inspired by Andrej Karpathy's micrograd.
    """

    def __init__(self, data: float, children: tuple = (), op: str = ""):
        self.data = float(data)
        self.grad = 0.0
        self._backward = lambda: None
        self._prev = set(children)
        self._op = op

    def __repr__(self):
        return f"Value(data={self.data:.4f}, grad={self.grad:.4f})"

    def __add__(self, other):
        other = other if isinstance(other, Value) else Value(other)
        out = Value(self.data + other.data, (self, other), "+")

        def _backward():
            self.grad += out.grad
            other.grad += out.grad
        out._backward = _backward
        return out

    def __radd__(self, other):
        return self + other

    def __mul__(self, other):
        other = other if isinstance(other, Value) else Value(other)
        out = Value(self.data * other.data, (self, other), "*")

        def _backward():
            self.grad += other.data * out.grad
            other.grad += self.data * out.grad
        out._backward = _backward
        return out

    def __rmul__(self, other):
        return self * other

    def __sub__(self, other):
        return self + (-other)

    def __rsub__(self, other):
        return (-self) + other

    def __neg__(self):
        return self * -1

    def __truediv__(self, other):
        return self * other ** -1

    def __pow__(self, exponent):
        assert isinstance(exponent, (int, float))
        out = Value(self.data ** exponent, (self,), f"**{exponent}")

        def _backward():
            self.grad += exponent * (self.data ** (exponent - 1)) * out.grad
        out._backward = _backward
        return out

    def relu(self):
        out = Value(max(0, self.data), (self,), "relu")

        def _backward():
            self.grad += (out.data > 0) * out.grad
        out._backward = _backward
        return out

    def tanh(self):
        t = np.tanh(self.data)
        out = Value(t, (self,), "tanh")

        def _backward():
            self.grad += (1 - t ** 2) * out.grad
        out._backward = _backward
        return out

    def exp(self):
        e = np.exp(self.data)
        out = Value(e, (self,), "exp")

        def _backward():
            self.grad += e * out.grad
        out._backward = _backward
        return out

    def log(self):
        out = Value(np.log(self.data), (self,), "log")

        def _backward():
            self.grad += (1.0 / self.data) * out.grad
        out._backward = _backward
        return out

    def backward(self):
        """Compute gradients via reverse-mode autodiff (backpropagation)."""
        topo = []
        visited = set()

        def build_topo(v):
            if v not in visited:
                visited.add(v)
                for child in v._prev:
                    build_topo(child)
                topo.append(v)

        build_topo(self)
        self.grad = 1.0

        for v in reversed(topo):
            v._backward()

    def zero_grad(self):
        """Reset gradient to zero."""
        self.grad = 0.0


class Neuron:
    """Single neuron with weights, bias, and optional activation."""

    def __init__(self, n_inputs: int, nonlin: bool = True):
        self.w = [Value(np.random.uniform(-1, 1)) for _ in range(n_inputs)]
        self.b = Value(0.0)
        self.nonlin = nonlin

    def __call__(self, x: list[Value]) -> Value:
        act = sum((wi * xi for wi, xi in zip(self.w, x)), self.b)
        return act.relu() if self.nonlin else act

    def parameters(self) -> list[Value]:
        return self.w + [self.b]


class Layer:
    """Layer of neurons."""

    def __init__(self, n_inputs: int, n_outputs: int, nonlin: bool = True):
        self.neurons = [Neuron(n_inputs, nonlin) for _ in range(n_outputs)]

    def __call__(self, x: list[Value]) -> list[Value]:
        out = [n(x) for n in self.neurons]
        return out[0] if len(out) == 1 else out

    def parameters(self) -> list[Value]:
        return [p for n in self.neurons for p in n.parameters()]


class MLP:
    """Multi-layer perceptron using autograd Values."""

    def __init__(self, n_inputs: int, layer_sizes: list[int]):
        sizes = [n_inputs] + layer_sizes
        self.layers = [
            Layer(sizes[i], sizes[i + 1], nonlin=(i != len(layer_sizes) - 1))
            for i in range(len(layer_sizes))
        ]

    def __call__(self, x: list[Value]) -> list[Value] | Value:
        for layer in self.layers:
            x = layer(x)
        return x

    def parameters(self) -> list[Value]:
        return [p for layer in self.layers for p in layer.parameters()]

    def zero_grad(self):
        for p in self.parameters():
            p.zero_grad()

"""TinyTorch optimizers module.

Extracted from CS249R Module 07: Optimizers.
NumPy-only implementation for educational purposes.
"""

from __future__ import annotations

import numpy as np

from cohezion.tinytorch.tensor import Tensor


class SGD:
    """Stochastic Gradient Descent optimizer.

    Updates parameters: w = w - lr * gradient
    With momentum: v = momentum * v - lr * gradient; w = w + v
    """

    def __init__(self, parameters: list[Tensor], lr: float = 0.01, momentum: float = 0.0):
        self.parameters = parameters
        self.lr = lr
        self.momentum = momentum
        self.velocities = [np.zeros_like(p.data) for p in parameters]

    def step(self, gradients: list[Tensor]):
        for i, (param, grad) in enumerate(zip(self.parameters, gradients)):
            if self.momentum > 0:
                self.velocities[i] = self.momentum * self.velocities[i] - self.lr * grad.data
                param.data += self.velocities[i]
            else:
                param.data -= self.lr * grad.data

    def zero_grad(self):
        pass  # Gradients managed externally in this simple implementation


class Adam:
    """Adam optimizer: adaptive learning rates with momentum.

    Combines benefits of AdaGrad (adaptive) and RMSProp (momentum).
    Default hyperparameters from the original paper (Kingma & Ba, 2015).
    """

    def __init__(
        self,
        parameters: list[Tensor],
        lr: float = 0.001,
        beta1: float = 0.9,
        beta2: float = 0.999,
        eps: float = 1e-8,
    ):
        self.parameters = parameters
        self.lr = lr
        self.beta1 = beta1
        self.beta2 = beta2
        self.eps = eps
        self.t = 0
        self.m = [np.zeros_like(p.data) for p in parameters]  # First moment
        self.v = [np.zeros_like(p.data) for p in parameters]  # Second moment

    def step(self, gradients: list[Tensor]):
        self.t += 1
        for i, (param, grad) in enumerate(zip(self.parameters, gradients)):
            self.m[i] = self.beta1 * self.m[i] + (1 - self.beta1) * grad.data
            self.v[i] = self.beta2 * self.v[i] + (1 - self.beta2) * grad.data ** 2

            # Bias correction
            m_hat = self.m[i] / (1 - self.beta1 ** self.t)
            v_hat = self.v[i] / (1 - self.beta2 ** self.t)

            param.data -= self.lr * m_hat / (np.sqrt(v_hat) + self.eps)


class RMSProp:
    """RMSProp: adaptive learning rate using running average of squared gradients."""

    def __init__(
        self,
        parameters: list[Tensor],
        lr: float = 0.001,
        alpha: float = 0.99,
        eps: float = 1e-8,
    ):
        self.parameters = parameters
        self.lr = lr
        self.alpha = alpha
        self.eps = eps
        self.v = [np.zeros_like(p.data) for p in parameters]

    def step(self, gradients: list[Tensor]):
        for i, (param, grad) in enumerate(zip(self.parameters, gradients)):
            self.v[i] = self.alpha * self.v[i] + (1 - self.alpha) * grad.data ** 2
            param.data -= self.lr * grad.data / (np.sqrt(self.v[i]) + self.eps)


class LearningRateScheduler:
    """Adjusts learning rate during training."""

    @staticmethod
    def step_decay(initial_lr: float, epoch: int, drop_rate: float = 0.5, epochs_drop: int = 10):
        return initial_lr * (drop_rate ** (epoch // epochs_drop))

    @staticmethod
    def cosine_annealing(initial_lr: float, epoch: int, total_epochs: int):
        return initial_lr * 0.5 * (1 + np.cos(np.pi * epoch / total_epochs))

    @staticmethod
    def warmup_cosine(initial_lr: float, epoch: int, warmup_epochs: int, total_epochs: int):
        if epoch < warmup_epochs:
            return initial_lr * epoch / warmup_epochs
        return LearningRateScheduler.cosine_annealing(
            initial_lr, epoch - warmup_epochs, total_epochs - warmup_epochs
        )


OPTIMIZERS = {"sgd": SGD, "adam": Adam, "rmsprop": RMSProp}

"""TinyTorch convolutions module.

Extracted from CS249R Module 09: Convolutional Neural Networks.
NumPy-only implementation for educational purposes.
"""

from __future__ import annotations

import numpy as np

from cohezion.tinytorch.tensor import Tensor


def conv2d(
    input_tensor: Tensor,
    kernel: Tensor,
    stride: int = 1,
    padding: int = 0,
) -> Tensor:
    """2D convolution operation.

    input_tensor: shape (H, W) or (C_in, H, W)
    kernel: shape (K_h, K_w) or (C_out, C_in, K_h, K_w)
    """
    data = input_tensor.data
    k = kernel.data

    # Handle simple 2D case
    if data.ndim == 2 and k.ndim == 2:
        return _conv2d_single(data, k, stride, padding)

    # Handle multi-channel case
    if data.ndim == 3 and k.ndim == 4:
        return _conv2d_multi(data, k, stride, padding)

    raise ValueError(f"Unsupported shapes: input {data.shape}, kernel {k.shape}")


def _conv2d_single(data: np.ndarray, kernel: np.ndarray, stride: int, padding: int) -> Tensor:
    """Single-channel 2D convolution."""
    if padding > 0:
        data = np.pad(data, padding, mode="constant")

    h, w = data.shape
    kh, kw = kernel.shape
    out_h = (h - kh) // stride + 1
    out_w = (w - kw) // stride + 1

    output = np.zeros((out_h, out_w), dtype=np.float32)
    for i in range(out_h):
        for j in range(out_w):
            region = data[i * stride:i * stride + kh, j * stride:j * stride + kw]
            output[i, j] = np.sum(region * kernel)

    return Tensor(output)


def _conv2d_multi(data: np.ndarray, kernels: np.ndarray, stride: int, padding: int) -> Tensor:
    """Multi-channel 2D convolution."""
    c_out, c_in, kh, kw = kernels.shape

    if padding > 0:
        data = np.pad(data, ((0, 0), (padding, padding), (padding, padding)), mode="constant")

    _, h, w = data.shape
    out_h = (h - kh) // stride + 1
    out_w = (w - kw) // stride + 1

    output = np.zeros((c_out, out_h, out_w), dtype=np.float32)
    for oc in range(c_out):
        for i in range(out_h):
            for j in range(out_w):
                region = data[:, i * stride:i * stride + kh, j * stride:j * stride + kw]
                output[oc, i, j] = np.sum(region * kernels[oc])

    return Tensor(output)


def max_pool2d(input_tensor: Tensor, kernel_size: int = 2, stride: int | None = None) -> Tensor:
    """2D max pooling."""
    if stride is None:
        stride = kernel_size

    data = input_tensor.data
    if data.ndim == 2:
        h, w = data.shape
        out_h = (h - kernel_size) // stride + 1
        out_w = (w - kernel_size) // stride + 1
        output = np.zeros((out_h, out_w), dtype=np.float32)
        for i in range(out_h):
            for j in range(out_w):
                region = data[i * stride:i * stride + kernel_size,
                              j * stride:j * stride + kernel_size]
                output[i, j] = np.max(region)
        return Tensor(output)

    if data.ndim == 3:
        c, h, w = data.shape
        out_h = (h - kernel_size) // stride + 1
        out_w = (w - kernel_size) // stride + 1
        output = np.zeros((c, out_h, out_w), dtype=np.float32)
        for ch in range(c):
            for i in range(out_h):
                for j in range(out_w):
                    region = data[ch, i * stride:i * stride + kernel_size,
                                  j * stride:j * stride + kernel_size]
                    output[ch, i, j] = np.max(region)
        return Tensor(output)

    raise ValueError(f"Expected 2D or 3D input, got {data.ndim}D")


def avg_pool2d(input_tensor: Tensor, kernel_size: int = 2, stride: int | None = None) -> Tensor:
    """2D average pooling."""
    if stride is None:
        stride = kernel_size

    data = input_tensor.data
    h, w = data.shape[-2], data.shape[-1]
    out_h = (h - kernel_size) // stride + 1
    out_w = (w - kernel_size) // stride + 1

    if data.ndim == 2:
        output = np.zeros((out_h, out_w), dtype=np.float32)
        for i in range(out_h):
            for j in range(out_w):
                region = data[i * stride:i * stride + kernel_size,
                              j * stride:j * stride + kernel_size]
                output[i, j] = np.mean(region)
        return Tensor(output)

    raise ValueError(f"Expected 2D input, got {data.ndim}D")


class Conv2d:
    """Convolutional layer with learnable kernels."""

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0):
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding

        scale = np.sqrt(2.0 / (in_channels * kernel_size * kernel_size))
        self.weights = Tensor(
            np.random.randn(out_channels, in_channels, kernel_size, kernel_size) * scale
        )
        self.bias = Tensor(np.zeros(out_channels))

    def forward(self, x: Tensor) -> Tensor:
        result = conv2d(x, self.weights, self.stride, self.padding)
        # Add bias per channel
        for c in range(self.out_channels):
            result.data[c] += self.bias.data[c]
        return result

    def __call__(self, x: Tensor) -> Tensor:
        return self.forward(x)

    def parameters(self) -> list[Tensor]:
        return [self.weights, self.bias]


class MaxPool2d:
    """Max pooling layer."""

    def __init__(self, kernel_size: int = 2, stride: int | None = None):
        self.kernel_size = kernel_size
        self.stride = stride

    def forward(self, x: Tensor) -> Tensor:
        return max_pool2d(x, self.kernel_size, self.stride)

    def __call__(self, x: Tensor) -> Tensor:
        return self.forward(x)

