"""TinyTorch activations module.

Extracted from CS249R Module 02: Activation Functions.
NumPy-only implementation for educational purposes.
"""

from __future__ import annotations

import numpy as np

from cohezion.tinytorch.tensor import Tensor


def relu(x: Tensor) -> Tensor:
    """ReLU: f(x) = max(0, x). Most common activation for hidden layers."""
    return Tensor(np.maximum(0, x.data))


def relu_derivative(x: Tensor) -> Tensor:
    """ReLU gradient: 1 if x > 0, else 0."""
    return Tensor((x.data > 0).astype(np.float32))


def sigmoid(x: Tensor) -> Tensor:
    """Sigmoid: f(x) = 1/(1+exp(-x)). Maps to (0,1) for binary classification."""
    clipped = np.clip(x.data, -500, 500)
    return Tensor(1.0 / (1.0 + np.exp(-clipped)))


def sigmoid_derivative(x: Tensor) -> Tensor:
    """Sigmoid gradient: s(x) * (1 - s(x))."""
    s = sigmoid(x)
    return Tensor(s.data * (1 - s.data))


def tanh(x: Tensor) -> Tensor:
    """Tanh: maps to (-1,1)."""
    return Tensor(np.tanh(x.data))


def tanh_derivative(x: Tensor) -> Tensor:
    """Tanh gradient: 1 - tanh(x)^2."""
    t = np.tanh(x.data)
    return Tensor(1.0 - t ** 2)


def leaky_relu(x: Tensor, alpha: float = 0.01) -> Tensor:
    """Leaky ReLU: allows small gradient for negative values."""
    return Tensor(np.where(x.data > 0, x.data, alpha * x.data))


def softmax(x: Tensor, axis: int = -1) -> Tensor:
    """Softmax: converts logits to probabilities that sum to 1."""
    shifted = x.data - x.data.max(axis=axis, keepdims=True)
    exp_x = np.exp(shifted)
    return Tensor(exp_x / exp_x.sum(axis=axis, keepdims=True))


def gelu(x: Tensor) -> Tensor:
    """GELU: Gaussian Error Linear Unit. Used in Transformers."""
    return Tensor(0.5 * x.data * (1 + np.tanh(
        np.sqrt(2 / np.pi) * (x.data + 0.044715 * x.data ** 3)
    )))


def swish(x: Tensor, beta: float = 1.0) -> Tensor:
    """Swish: f(x) = x * sigmoid(beta*x). Self-gated activation."""
    sig = 1.0 / (1.0 + np.exp(-beta * np.clip(x.data, -500, 500)))
    return Tensor(x.data * sig)


ACTIVATIONS = {
    "relu": relu, "sigmoid": sigmoid, "tanh": tanh,
    "leaky_relu": leaky_relu, "softmax": softmax,
    "gelu": gelu, "swish": swish,
}

"""TinyTorch layers module.

Extracted from CS249R Module 03: Neural Network Layers.
NumPy-only implementation for educational purposes.
"""

from __future__ import annotations

import numpy as np

from cohezion.tinytorch.tensor import Tensor


class Linear:
    """Fully connected layer: y = xW + b.

    Uses Xavier/Glorot initialization for stable gradient flow.
    """

    def __init__(self, in_features: int, out_features: int, bias: bool = True):
        self.in_features = in_features
        self.out_features = out_features
        scale = np.sqrt(2.0 / (in_features + out_features))
        self.weights = Tensor(np.random.randn(in_features, out_features) * scale)
        self.bias = Tensor(np.zeros(out_features)) if bias else None
        self.input_cache = None

    def forward(self, x: Tensor) -> Tensor:
        self.input_cache = x
        result = x @ self.weights
        if self.bias is not None:
            result = result + self.bias
        return result

    def __call__(self, x: Tensor) -> Tensor:
        return self.forward(x)

    def parameters(self) -> list[Tensor]:
        params = [self.weights]
        if self.bias is not None:
            params.append(self.bias)
        return params


class BatchNorm:
    """Batch normalization: normalize activations across the batch."""

    def __init__(self, num_features: int, momentum: float = 0.1, eps: float = 1e-5):
        self.num_features = num_features
        self.momentum = momentum
        self.eps = eps
        self.gamma = Tensor(np.ones(num_features))
        self.beta = Tensor(np.zeros(num_features))
        self.running_mean = np.zeros(num_features)
        self.running_var = np.ones(num_features)
        self.training = True

    def forward(self, x: Tensor) -> Tensor:
        if self.training:
            mean = x.data.mean(axis=0)
            var = x.data.var(axis=0)
            self.running_mean = (1 - self.momentum) * self.running_mean + self.momentum * mean
            self.running_var = (1 - self.momentum) * self.running_var + self.momentum * var
        else:
            mean, var = self.running_mean, self.running_var
        x_norm = (x.data - mean) / np.sqrt(var + self.eps)
        return Tensor(self.gamma.data * x_norm + self.beta.data)

    def __call__(self, x: Tensor) -> Tensor:
        return self.forward(x)

    def parameters(self) -> list[Tensor]:
        return [self.gamma, self.beta]


class Dropout:
    """Dropout: randomly zero elements during training for regularization."""

    def __init__(self, p: float = 0.5):
        self.p = p
        self.training = True

    def forward(self, x: Tensor) -> Tensor:
        if not self.training:
            return x
        mask = (np.random.rand(*x.shape) > self.p).astype(np.float32)
        return Tensor(x.data * mask / (1 - self.p))

    def __call__(self, x: Tensor) -> Tensor:
        return self.forward(x)


class Sequential:
    """Container that chains layers sequentially."""

    def __init__(self, layers: list):
        self.layers = layers

    def forward(self, x: Tensor) -> Tensor:
        for layer in self.layers:
            x = layer(x)
        return x

    def __call__(self, x: Tensor) -> Tensor:
        return self.forward(x)

    def parameters(self) -> list[Tensor]:
        params = []
        for layer in self.layers:
            if hasattr(layer, "parameters"):
                params.extend(layer.parameters())
        return params

"""TinyTorch losses module.

Extracted from CS249R Module 04: Loss Functions.
NumPy-only implementation for educational purposes.
"""

from __future__ import annotations

import numpy as np

from cohezion.tinytorch.tensor import Tensor


def mse_loss(predictions: Tensor, targets: Tensor) -> Tensor:
    """Mean Squared Error loss for regression."""
    diff = predictions.data - targets.data
    return Tensor(np.mean(diff ** 2))


def mse_loss_gradient(predictions: Tensor, targets: Tensor) -> Tensor:
    """Gradient of MSE loss w.r.t. predictions."""
    n = predictions.data.size
    return Tensor(2.0 * (predictions.data - targets.data) / n)


def cross_entropy_loss(logits: Tensor, targets: Tensor) -> Tensor:
    """Cross-entropy loss for multi-class classification."""
    shifted = logits.data - logits.data.max(axis=-1, keepdims=True)
    exp_logits = np.exp(shifted)
    probs = exp_logits / exp_logits.sum(axis=-1, keepdims=True)
    probs = np.clip(probs, 1e-7, 1 - 1e-7)

    if targets.data.ndim == 1:
        batch_size = logits.data.shape[0]
        log_probs = -np.log(probs[np.arange(batch_size), targets.data.astype(int)])
        return Tensor(np.mean(log_probs))
    return Tensor(-np.mean(np.sum(targets.data * np.log(probs), axis=-1)))


def binary_cross_entropy_loss(predictions: Tensor, targets: Tensor) -> Tensor:
    """Binary cross-entropy for binary classification."""
    p = np.clip(predictions.data, 1e-7, 1 - 1e-7)
    loss = -(targets.data * np.log(p) + (1 - targets.data) * np.log(1 - p))
    return Tensor(np.mean(loss))


def huber_loss(predictions: Tensor, targets: Tensor, delta: float = 1.0) -> Tensor:
    """Huber loss: MSE for small errors, MAE for large. Robust to outliers."""
    diff = np.abs(predictions.data - targets.data)
    loss = np.where(diff <= delta, 0.5 * diff ** 2, delta * (diff - 0.5 * delta))
    return Tensor(np.mean(loss))


def l1_loss(predictions: Tensor, targets: Tensor) -> Tensor:
    """L1 (Mean Absolute Error) loss."""
    return Tensor(np.mean(np.abs(predictions.data - targets.data)))


LOSSES = {
    "mse": mse_loss, "cross_entropy": cross_entropy_loss,
    "binary_cross_entropy": binary_cross_entropy_loss,
    "huber": huber_loss, "l1": l1_loss,
}

"""TinyTorch dataloader module.

Extracted from CS249R Module 05: Data Loading.
NumPy-only implementation for educational purposes.
"""

from __future__ import annotations

import numpy as np

from cohezion.tinytorch.tensor import Tensor


class Dataset:
    """Base dataset class. Subclass and implement __getitem__ and __len__."""

    def __getitem__(self, idx: int) -> tuple:
        raise NotImplementedError

    def __len__(self) -> int:
        raise NotImplementedError


class TensorDataset(Dataset):
    """Dataset wrapping tensors. Each sample is a tuple of corresponding elements."""

    def __init__(self, *tensors: Tensor):
        assert all(t.shape[0] == tensors[0].shape[0] for t in tensors)
        self.tensors = tensors

    def __getitem__(self, idx: int) -> tuple[Tensor, ...]:
        return tuple(Tensor(t.data[idx]) for t in self.tensors)

    def __len__(self) -> int:
        return self.tensors[0].shape[0]


class DataLoader:
    """Iterable data loader with batching and shuffling."""

    def __init__(self, dataset: Dataset, batch_size: int = 32, shuffle: bool = True):
        self.dataset = dataset
        self.batch_size = batch_size
        self.shuffle = shuffle

    def __iter__(self):
        n = len(self.dataset)
        indices = np.arange(n)
        if self.shuffle:
            np.random.shuffle(indices)

        for start in range(0, n, self.batch_size):
            batch_indices = indices[start:start + self.batch_size]
            batch = [self.dataset[i] for i in batch_indices]

            # Collate: stack each element across the batch
            collated = []
            for elem_idx in range(len(batch[0])):
                stacked = np.stack([b[elem_idx].data for b in batch])
                collated.append(Tensor(stacked))

            yield tuple(collated)

    def __len__(self) -> int:
        return (len(self.dataset) + self.batch_size - 1) // self.batch_size


def train_test_split(
    *arrays: Tensor,
    test_size: float = 0.2,
    seed: int | None = None,
) -> list[Tensor]:
    """Split arrays into train and test sets."""
    if seed is not None:
        np.random.seed(seed)

    n = arrays[0].shape[0]
    indices = np.random.permutation(n)
    split_idx = int(n * (1 - test_size))
    train_idx, test_idx = indices[:split_idx], indices[split_idx:]

    result = []
    for arr in arrays:
        result.append(Tensor(arr.data[train_idx]))
        result.append(Tensor(arr.data[test_idx]))
    return result

"""TinyTorch autograd module.

Extracted from CS249R Module 06: Automatic Differentiation.
NumPy-only implementation for educational purposes.
"""

from __future__ import annotations

import numpy as np


class Value:
    """Scalar value with automatic differentiation.

    Tracks computation graph and computes gradients via backpropagation.
    Inspired by Andrej Karpathy's micrograd.
    """

    def __init__(self, data: float, children: tuple = (), op: str = ""):
        self.data = float(data)
        self.grad = 0.0
        self._backward = lambda: None
        self._prev = set(children)
        self._op = op

    def __repr__(self):
        return f"Value(data={self.data:.4f}, grad={self.grad:.4f})"

    def __add__(self, other):
        other = other if isinstance(other, Value) else Value(other)
        out = Value(self.data + other.data, (self, other), "+")

        def _backward():
            self.grad += out.grad
            other.grad += out.grad
        out._backward = _backward
        return out

    def __radd__(self, other):
        return self + other

    def __mul__(self, other):
        other = other if isinstance(other, Value) else Value(other)
        out = Value(self.data * other.data, (self, other), "*")

        def _backward():
            self.grad += other.data * out.grad
            other.grad += self.data * out.grad
        out._backward = _backward
        return out

    def __rmul__(self, other):
        return self * other

    def __sub__(self, other):
        return self + (-other)

    def __rsub__(self, other):
        return (-self) + other

    def __neg__(self):
        return self * -1

    def __truediv__(self, other):
        return self * other ** -1

    def __pow__(self, exponent):
        assert isinstance(exponent, (int, float))
        out = Value(self.data ** exponent, (self,), f"**{exponent}")

        def _backward():
            self.grad += exponent * (self.data ** (exponent - 1)) * out.grad
        out._backward = _backward
        return out

    def relu(self):
        out = Value(max(0, self.data), (self,), "relu")

        def _backward():
            self.grad += (out.data > 0) * out.grad
        out._backward = _backward
        return out

    def tanh(self):
        t = np.tanh(self.data)
        out = Value(t, (self,), "tanh")

        def _backward():
            self.grad += (1 - t ** 2) * out.grad
        out._backward = _backward
        return out

    def exp(self):
        e = np.exp(self.data)
        out = Value(e, (self,), "exp")

        def _backward():
            self.grad += e * out.grad
        out._backward = _backward
        return out

    def log(self):
        out = Value(np.log(self.data), (self,), "log")

        def _backward():
            self.grad += (1.0 / self.data) * out.grad
        out._backward = _backward
        return out

    def backward(self):
        """Compute gradients via reverse-mode autodiff (backpropagation)."""
        topo = []
        visited = set()

        def build_topo(v):
            if v not in visited:
                visited.add(v)
                for child in v._prev:
                    build_topo(child)
                topo.append(v)

        build_topo(self)
        self.grad = 1.0

        for v in reversed(topo):
            v._backward()

    def zero_grad(self):
        """Reset gradient to zero."""
        self.grad = 0.0


class Neuron:
    """Single neuron with weights, bias, and optional activation."""

    def __init__(self, n_inputs: int, nonlin: bool = True):
        self.w = [Value(np.random.uniform(-1, 1)) for _ in range(n_inputs)]
        self.b = Value(0.0)
        self.nonlin = nonlin

    def __call__(self, x: list[Value]) -> Value:
        act = sum((wi * xi for wi, xi in zip(self.w, x)), self.b)
        return act.relu() if self.nonlin else act

    def parameters(self) -> list[Value]:
        return self.w + [self.b]


class Layer:
    """Layer of neurons."""

    def __init__(self, n_inputs: int, n_outputs: int, nonlin: bool = True):
        self.neurons = [Neuron(n_inputs, nonlin) for _ in range(n_outputs)]

    def __call__(self, x: list[Value]) -> list[Value]:
        out = [n(x) for n in self.neurons]
        return out[0] if len(out) == 1 else out

    def parameters(self) -> list[Value]:
        return [p for n in self.neurons for p in n.parameters()]


class MLP:
    """Multi-layer perceptron using autograd Values."""

    def __init__(self, n_inputs: int, layer_sizes: list[int]):
        sizes = [n_inputs] + layer_sizes
        self.layers = [
            Layer(sizes[i], sizes[i + 1], nonlin=(i != len(layer_sizes) - 1))
            for i in range(len(layer_sizes))
        ]

    def __call__(self, x: list[Value]) -> list[Value] | Value:
        for layer in self.layers:
            x = layer(x)
        return x

    def parameters(self) -> list[Value]:
