    PE(pos, 2i)   = sin(pos / 10000^(2i/d_model))
    PE(pos, 2i+1) = cos(pos / 10000^(2i/d_model))
    """

    def __init__(self, d_model: int, max_len: int = 5000):
        self.d_model = d_model
        pe = np.zeros((max_len, d_model), dtype=np.float32)
        position = np.arange(0, max_len)[:, np.newaxis]
        div_term = np.exp(np.arange(0, d_model, 2) * -(np.log(10000.0) / d_model))
        pe[:, 0::2] = np.sin(position * div_term)
        pe[:, 1::2] = np.cos(position * div_term[:d_model // 2])
        self.pe = Tensor(pe)

    def forward(self, x: Tensor) -> Tensor:
        """Add positional encoding to input embeddings."""
        seq_len = x.shape[-2] if x.data.ndim > 1 else x.shape[0]
        return Tensor(x.data + self.pe.data[:seq_len])

    def __call__(self, x: Tensor) -> Tensor:
        return self.forward(x)


def cosine_similarity(a: Tensor, b: Tensor) -> float:
    """Compute cosine similarity between two vectors."""
    dot = np.dot(a.data.flatten(), b.data.flatten())
    norm_a = np.linalg.norm(a.data)
    norm_b = np.linalg.norm(b.data)
    if norm_a == 0 or norm_b == 0:
        return 0.0
    return float(dot / (norm_a * norm_b))

"""TinyTorch transformers module.

Extracted from CS249R Module 13: Transformer Architecture.
NumPy-only implementation for educational purposes.
"""

from __future__ import annotations

import numpy as np

from cohezion.tinytorch.tensor import Tensor
from cohezion.tinytorch.attention import MultiHeadAttention
from cohezion.tinytorch.layers import Linear


class LayerNorm:
    """Layer normalization: normalize across features (not batch)."""

    def __init__(self, d_model: int, eps: float = 1e-6):
        self.d_model = d_model
        self.eps = eps
        self.gamma = Tensor(np.ones(d_model, dtype=np.float32))
        self.beta = Tensor(np.zeros(d_model, dtype=np.float32))

    def forward(self, x: Tensor) -> Tensor:
        mean = x.data.mean(axis=-1, keepdims=True)
        var = x.data.var(axis=-1, keepdims=True)
        x_norm = (x.data - mean) / np.sqrt(var + self.eps)
        return Tensor(self.gamma.data * x_norm + self.beta.data)

    def __call__(self, x: Tensor) -> Tensor:
        return self.forward(x)


class FeedForward:
    """Position-wise feed-forward network: FFN(x) = ReLU(xW1+b1)W2+b2."""

    def __init__(self, d_model: int, d_ff: int | None = None):
        d_ff = d_ff or d_model * 4
        self.linear1 = Linear(d_model, d_ff)
        self.linear2 = Linear(d_ff, d_model)

    def forward(self, x: Tensor) -> Tensor:
        hidden = self.linear1(x)
        activated = Tensor(np.maximum(0, hidden.data))  # ReLU
        return self.linear2(activated)

    def __call__(self, x: Tensor) -> Tensor:
        return self.forward(x)

    def parameters(self) -> list[Tensor]:
        return self.linear1.parameters() + self.linear2.parameters()


class TransformerEncoderLayer:
    """Single transformer encoder layer: self-attention + feed-forward."""

    def __init__(self, d_model: int, num_heads: int, d_ff: int | None = None):
        self.attention = MultiHeadAttention(d_model, num_heads)
        self.feed_forward = FeedForward(d_model, d_ff)
        self.norm1 = LayerNorm(d_model)
        self.norm2 = LayerNorm(d_model)

    def forward(self, x: Tensor, mask: Tensor | None = None) -> Tensor:
        # Self-attention with residual connection and layer norm
        attn_out = self.attention(x, x, x, mask)
        x = self.norm1(Tensor(x.data + attn_out.data))

        # Feed-forward with residual connection and layer norm
        ff_out = self.feed_forward(x)
        x = self.norm2(Tensor(x.data + ff_out.data))
        return x

    def __call__(self, x: Tensor, mask: Tensor | None = None) -> Tensor:
        return self.forward(x, mask)

    def parameters(self) -> list[Tensor]:
        params = self.attention.parameters()
        params += self.feed_forward.parameters()
        params += [self.norm1.gamma, self.norm1.beta]
        params += [self.norm2.gamma, self.norm2.beta]
        return params


class TransformerEncoder:
    """Stack of transformer encoder layers."""

    def __init__(self, d_model: int, num_heads: int, num_layers: int, d_ff: int | None = None):
        self.layers = [
            TransformerEncoderLayer(d_model, num_heads, d_ff)
            for _ in range(num_layers)
        ]

    def forward(self, x: Tensor, mask: Tensor | None = None) -> Tensor:
        for layer in self.layers:
            x = layer(x, mask)
        return x

    def __call__(self, x: Tensor, mask: Tensor | None = None) -> Tensor:
        return self.forward(x, mask)

    def parameters(self) -> list[Tensor]:
        return [p for layer in self.layers for p in layer.parameters()]

