from __future__ import annotations

import time
from dataclasses import dataclass, field

import numpy as np


@dataclass
class ProfileResult:
    """Result of profiling a single operation."""
    name: str
    time_ms: float
    memory_bytes: int = 0
    flops: int = 0


@dataclass
class ModelProfile:
    """Aggregate profile of a model."""
    results: list[ProfileResult] = field(default_factory=list)

    @property
    def total_time_ms(self) -> float:
        return sum(r.time_ms for r in self.results)

    @property
    def total_memory_bytes(self) -> int:
        return sum(r.memory_bytes for r in self.results)

    def summary(self) -> str:
        lines = [f"{'Layer':<30} {'Time (ms)':<12} {'Memory (KB)':<12}"]
        lines.append("-" * 54)
        for r in self.results:
            lines.append(f"{r.name:<30} {r.time_ms:<12.3f} {r.memory_bytes / 1024:<12.1f}")
        lines.append("-" * 54)
        lines.append(f"{'TOTAL':<30} {self.total_time_ms:<12.3f} {self.total_memory_bytes / 1024:<12.1f}")
        return "\n".join(lines)


def time_operation(func, *args, warmup: int = 5, iterations: int = 50, **kwargs) -> ProfileResult:
    """Time a function with warmup and statistical analysis."""
    for _ in range(warmup):
        func(*args, **kwargs)

    times = []
    for _ in range(iterations):
        start = time.perf_counter_ns()
        result = func(*args, **kwargs)
        end = time.perf_counter_ns()
        times.append((end - start) / 1e6)

    return ProfileResult(
        name=getattr(func, "__name__", str(func)),
        time_ms=float(np.median(times)),
    )


def estimate_flops_linear(in_features: int, out_features: int, batch_size: int = 1) -> int:
    """Estimate FLOPs for a linear layer: 2 * batch * in * out."""
