def estimate_flops_conv2d(
    in_channels: int, out_channels: int, kernel_size: int,
    output_h: int, output_w: int
) -> int:
    """Estimate FLOPs for a conv2d layer."""
    return 2 * out_channels * in_channels * kernel_size * kernel_size * output_h * output_w


def estimate_memory(shape: tuple, dtype_bytes: int = 4) -> int:
    """Estimate memory usage for a tensor."""
    return int(np.prod(shape)) * dtype_bytes


