from __future__ import annotations

import numpy as np

from cohezion.tinytorch.tensor import Tensor


def magnitude_pruning(weights: Tensor, sparsity: float = 0.5) -> tuple[Tensor, Tensor]:
    """Prune weights by magnitude: zero out smallest values.

    Returns (pruned_weights, binary_mask).
    """
    threshold = np.percentile(np.abs(weights.data), sparsity * 100)
    mask = (np.abs(weights.data) > threshold).astype(np.float32)
    return Tensor(weights.data * mask), Tensor(mask)


def structured_pruning(weights: Tensor, sparsity: float = 0.5, axis: int = 0) -> Tensor:
    """Prune entire rows/columns (structured) based on L2 norm."""
    norms = np.linalg.norm(weights.data, axis=axis)
    n_keep = max(1, int(len(norms) * (1 - sparsity)))
    keep_indices = np.argsort(norms)[-n_keep:]

    if axis == 0:
        return Tensor(weights.data[keep_indices])
    return Tensor(weights.data[:, keep_indices])


def low_rank_approximation(weights: Tensor, rank: int) -> tuple[Tensor, Tensor]:
    """Approximate weight matrix using SVD truncation.

    W ≈ U_r @ V_r^T where r << min(m, n).
    Returns (U_r, V_r) such that U_r @ V_r ≈ W.
    """
    U, S, Vt = np.linalg.svd(weights.data, full_matrices=False)
    U_r = U[:, :rank] * np.sqrt(S[:rank])
    V_r = Vt[:rank, :] * np.sqrt(S[:rank])[:, np.newaxis]
    return Tensor(U_r), Tensor(V_r)


def compute_sparsity(weights: Tensor) -> float:
    """Compute fraction of zero weights."""
    return float(np.mean(weights.data == 0))


def count_parameters(model) -> dict[str, int]:
    """Count total and non-zero parameters in a model."""
    if not hasattr(model, "parameters"):
        return {"total": 0, "nonzero": 0}

    total = 0
    nonzero = 0
    for param in model.parameters():
        total += param.size
        nonzero += int(np.count_nonzero(param.data))

    return {
        "total": total,
        "nonzero": nonzero,
        "pruned": total - nonzero,
        "sparsity": 1 - nonzero / total if total > 0 else 0,
    }

"""TinyTorch memoization module.

Extracted from CS249R Module 18: Memoization and Caching.
NumPy-only implementation for educational purposes.
"""

from __future__ import annotations

import hashlib
from collections import OrderedDict
from functools import wraps

import numpy as np

from cohezion.tinytorch.tensor import Tensor


class TensorCache:
    """LRU cache for tensor computations."""

    def __init__(self, max_size: int = 128):
        self.max_size = max_size
        self.cache: OrderedDict[str, Tensor] = OrderedDict()
        self.hits = 0
        self.misses = 0

    def _hash_key(self, *args) -> str:
        """Create a hash key from function arguments."""
        parts = []
        for arg in args:
            if isinstance(arg, Tensor):
                parts.append(hashlib.md5(arg.data.tobytes()).hexdigest())
            elif isinstance(arg, np.ndarray):
                parts.append(hashlib.md5(arg.tobytes()).hexdigest())
            else:
                parts.append(str(arg))
        return "|".join(parts)

    def get(self, key: str) -> Tensor | None:
        if key in self.cache:
            self.hits += 1
            self.cache.move_to_end(key)
            return self.cache[key]
        self.misses += 1
        return None

    def put(self, key: str, value: Tensor):
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.max_size:
            self.cache.popitem(last=False)

    @property
    def hit_rate(self) -> float:
        total = self.hits + self.misses
        return self.hits / total if total > 0 else 0.0

    def clear(self):
        self.cache.clear()
        self.hits = 0
        self.misses = 0


def cached_operation(cache: TensorCache):
    """Decorator to cache tensor operation results."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = cache._hash_key(*args)
            result = cache.get(key)
            if result is not None:
                return result
            result = func(*args, **kwargs)
            if isinstance(result, Tensor):
                cache.put(key, result)
            return result
        return wrapper
    return decorator


class GradientCheckpoint:
    """Trade compute for memory: recompute activations during backward pass."""

    def __init__(self):
        self.checkpoints: dict[str, Tensor] = {}

    def save(self, name: str, tensor: Tensor):
        self.checkpoints[name] = Tensor(tensor.data.copy())

    def load(self, name: str) -> Tensor | None:
        return self.checkpoints.get(name)

    def clear(self):
        self.checkpoints.clear()

    @property
    def memory_bytes(self) -> int:
        return sum(t.data.nbytes for t in self.checkpoints.values())

"""TinyTorch benchmarking module.

