from __future__ import annotations

import time
from dataclasses import dataclass, field

import numpy as np


@dataclass
class BenchmarkResult:
    """Result of a benchmark run."""
    name: str
    iterations: int
    times_ms: list[float] = field(default_factory=list)

    @property
    def mean_ms(self) -> float:
        return float(np.mean(self.times_ms))

    @property
    def median_ms(self) -> float:
        return float(np.median(self.times_ms))

    @property
    def p95_ms(self) -> float:
        return float(np.percentile(self.times_ms, 95))

    @property
    def p99_ms(self) -> float:
        return float(np.percentile(self.times_ms, 99))

    @property
    def std_ms(self) -> float:
        return float(np.std(self.times_ms))

    @property
    def throughput_qps(self) -> float:
        return 1000.0 / self.mean_ms if self.mean_ms > 0 else 0.0

    def summary(self) -> str:
        return (f"{self.name}: mean={self.mean_ms:.3f}ms, "
                f"p95={self.p95_ms:.3f}ms, p99={self.p99_ms:.3f}ms, "
                f"throughput={self.throughput_qps:.1f} QPS")


def benchmark(func, *args, warmup: int = 10, iterations: int = 100,
              name: str | None = None, **kwargs) -> BenchmarkResult:
    """Run a benchmark with warmup and statistical analysis."""
    name = name or getattr(func, "__name__", "unknown")

    # Warmup
    for _ in range(warmup):
        func(*args, **kwargs)

    # Timed runs
    times = []
    for _ in range(iterations):
        start = time.perf_counter_ns()
        func(*args, **kwargs)
        end = time.perf_counter_ns()
        times.append((end - start) / 1e6)

    return BenchmarkResult(name=name, iterations=iterations, times_ms=times)


def compare_implementations(implementations: dict[str, callable],
                            *args, warmup: int = 10, iterations: int = 100,
                            **kwargs) -> dict[str, BenchmarkResult]:
    """Compare multiple implementations of the same operation."""
    results = {}
    for name, func in implementations.items():
        results[name] = benchmark(func, *args, warmup=warmup,
                                  iterations=iterations, name=name, **kwargs)
    return results


def benchmark_report(results: dict[str, BenchmarkResult]) -> str:
    """Generate a comparison report from benchmark results."""
    lines = [f"{'Implementation':<25} {'Mean (ms)':<12} {'P95 (ms)':<12} {'P99 (ms)':<12} {'QPS':<10}"]
    lines.append("-" * 71)

    baseline_time = None
    for name, result in results.items():
        if baseline_time is None:
            baseline_time = result.mean_ms

        speedup = baseline_time / result.mean_ms if result.mean_ms > 0 else 0
        suffix = f" ({speedup:.1f}x)" if speedup != 1.0 else " (baseline)"

        lines.append(
            f"{name:<25} {result.mean_ms:<12.3f} {result.p95_ms:<12.3f} "
            f"{result.p99_ms:<12.3f} {result.throughput_qps:<10.1f}{suffix}"
        )

    return "\n".join(lines)
